async function ensureFx(currencies){for(const cur of [...new Set(currencies.filter(Boolean).map(x=>String(x).toUpperCase()))]){if(cur==='EUR'){D.fxRates.EUR={rate:1,updated:Date.now()};continue}let cached=D.fxRates[cur];if(cached&&Date.now()-(+cached.updated||0)<21600000)continue;try{let r=await api.marketFx({from:cur,to:'EUR'});D.fxRates[cur]={rate:r.rate,updated:Date.now()};marketUsageAdd(1)}catch(e){if(q('uMarketState'))q('uMarketState').textContent='FX update issue: '+e.message}}}
