function nextMarketBatch(symbols){if(symbols.length<=8)return symbols;let out=[];for(let i=0;i<8;i++)out.push(symbols[(marketBatchCursor+i)%symbols.length]);marketBatchCursor=(marketBatchCursor+8)%symbols.length;return out}
