function renderMarketUsage(){let day=new Date().toISOString().slice(0,10),used=+(D.marketUsage[day]?.requests||0),left=Math.max(0,800-used),b=marketBudget();if(q('uMarket'))q('uMarket').textContent=left.toLocaleString();let state=used.toLocaleString()+' requests tracked today • '+left.toLocaleString()+' remaining • '+b.label;if(q('uMarketState'))q('uMarketState').textContent=state;let card=q('uMarketCardState');if(card)card.textContent=used.toLocaleString()+' used • '+b.label}
async function refreshMarketData(force=false){if(!api||!api.marketQuotes||marketRefreshing)return;let all=marketSymbols();if(!all.length)return;let symbols=nextMarketBatch(all),day=new Date().toISOString().slice(0,10),remaining=Math.max(0,800-(+D.marketUsage[day]?.requests||0)),now=Date.now(),wait=marketBudget().ms;if(!force&&remaining<symbols.length)return;if(!force&&now-marketLastRefresh<wait)return;marketRefreshing=true;if(q('watchBusy'))q('watchBusy').textContent='Updating prices…';try{let rows=await api.marketQuotes({symbols});let successful=0;rows.forEach(r=>{if(!r.ok)return;successful++;D.watch.filter(x=>x.ticker===r.symbol).forEach(x=>Object.assign(x,{price:r.price,change:r.change,percentChange:r.percentChange,currency:r.currency,exchange:r.exchange,isMarketOpen:r.isMarketOpen,marketUpdated:new Date().toISOString()}));D.holdings.filter(x=>x.ticker===r.symbol).forEach(x=>Object.assign(x,{current:r.price,currentCurrency:r.currency,change:r.change,percentChange:r.percentChange,exchange:r.exchange,isMarketOpen:r.isMarketOpen,marketUpdated:new Date().toISOString()}))});if(successful){marketUsageAdd(successful);await ensureFx(rows.filter(r=>r.ok).map(r=>r.currency));marketLastRefresh=now;localStorage.setItem(KEY,JSON.stringify(D));render();scheduleMarketRefresh()}}catch(e){if(q('uMarketState'))q('uMarketState').textContent='Market data: '+e.message}finally{marketRefreshing=false;if(q('watchBusy'))q('watchBusy').textContent=''}}
