let realized=D.transactions.filter(t=>t.type==='sell').reduce((s,t)=>s+(+t.realizedPL||0),0);if(q('pRealized')){q('pRealized').textContent=(realized>=0?'+':'')+eur(realized);q('pRealized').className='big '+(realized>=0?'positive':'negative')}let total=D.allocations.reduce((s,a)=>s+(+a.amount||0),0),budget=Math.max(0,+D.budget||0),left=budget-total,pct=budget?total/budget*100:0;q('monthlyBudget').value=budget;q('monthlyIncome').value=D.income||'';q('budgetTotal').textContent=eur(budget);q('planned').textContent=eur(total);q('remaining').textContent=eur(left);q('remaining').className='big '+(left<0?'negative':'');q('budgetUsed').textContent=pct.toFixed(0)+'%';q('dBudget').textContent=eur(budget);q('dBudgetLeft').textContent=eur(left)+' left to allocate';let pv=D.holdings.reduce((s,x)=>{let raw=(+x.shares||0)*(+x.current||+x.avg||0),v=toEur(raw,x.current?x.currentCurrency:'EUR');return s+(v??raw)},0),pi=D.holdings.reduce((s,x)=>s+(+x.shares||0)*(+x.avg||0),0),ppl=pv-pi;q('pValue').textContent=eur(pv);q('pInvested').textContent=eur(pi);q('pPL').textContent=(ppl>=0?'+':'')+eur(ppl);q('pPL').className=ppl>=0?'positive':'negative';if(q('portfolioConcentration')){let pos=portfolioPositions().sort((a,b)=>b.weightPct-a.weightPct);q('portfolioConcentration').innerHTML=pos.length?'<b>App-calculated concentration</b><br>'+pos.slice(0,6).map(x=>esc(x.ticker)+' — '+x.weightPct.toFixed(1)+'% • '+eur(x.valueEur)).join('<br>')+(pos.length>6?'<br><span class="muted">+'+(pos.length-6)+' more positions</span>':''):'Add investments to analyze concentration.'}
