q('schoolFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>maxSchoolFile){alert('Please choose a file smaller than 8 MB.');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{schoolAttachment={name:f.name,type:f.type||'application/octet-stream',size:f.size,data:String(reader.result).split(',')[1]||''};q('schoolAttachment').innerHTML='<div class="attach"><div><b>'+esc(f.name)+'</b><br><small>'+Math.ceil(f.size/1024)+' KB</small></div><button id="removeSchoolFile">Remove</button></div>';q('removeSchoolFile').onclick=()=>{schoolAttachment=null;q('schoolFile').value='';q('schoolAttachment').innerHTML='';setSchoolMode(schoolMode)};setSchoolMode(schoolMode)};reader.readAsDataURL(f)};
let sessionInput=0,sessionOutput=0,sessionRequests=0;
const usageCost=x=>(+x.input||0)*0.20/1000000+(+x.output||0)*1.20/1000000;
function usageTotals(filter){let z={requests:0,input:0,output:0};Object.entries(D.apiUsage||{}).filter(([d])=>filter(d)).forEach(([,v])=>{z.requests+=+v.requests||0;z.input+=+v.input||0;z.output+=+v.output||0});return z}
function renderUsage(){let today=new Date().toISOString().slice(0,10),month=today.slice(0,7),a=usageTotals(()=>true),m=usageTotals(d=>d.startsWith(month)),t=usageTotals(d=>d===today),fmt=x=>'$'+usageCost(x).toFixed(4);[['Today',t],['Month',m],['All',a]].forEach(([k,v])=>{if(q('u'+k+'Cost'))q('u'+k+'Cost').textContent=fmt(v);if(q('u'+k+'Meta'))q('u'+k+'Meta').textContent=v.requests.toLocaleString()+' requests'});if(q('uOpenAIState'))q('uOpenAIState').textContent='Tracked locally • '+a.input.toLocaleString()+' input tokens • '+a.output.toLocaleString()+' output tokens';if(q('uUsageRows'))q('uUsageRows').innerHTML=[['Today',t],['This month',m],['All time',a]].map(([n,v])=>'<tr><td><b>'+n+'</b></td><td>'+v.requests.toLocaleString()+'</td><td>'+v.input.toLocaleString()+'</td><td>'+v.output.toLocaleString()+'</td><td>'+fmt(v)+'</td></tr>').join('')}
function trackUsage(u){if(!u)return;sessionRequests++;let input=+u.input_tokens||0,output=+u.output_tokens||0;sessionInput+=input;sessionOutput+=output;let day=new Date().toISOString().slice(0,10),x=D.apiUsage[day]||(D.apiUsage[day]={requests:0,input:0,output:0});x.requests++;x.input+=input;x.output+=output;save();let s='This session: '+sessionRequests.toLocaleString()+' requests • '+sessionInput.toLocaleString()+' input tokens • '+sessionOutput.toLocaleString()+' output tokens';let el=q('usageState');if(el)el.textContent=s;renderUsage()}
const api=window.desktopAPI;
q('openCommand').onclick=openCommandPalette;
q('commandPalette').onclick=e=>{if(e.target===q('commandPalette'))closeCommandPalette()};
q('commandInput').oninput=()=>{commandSelection=0;renderCommandResults()};
q('commandInput').onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();commandSelection=Math.min(commandSelection+1,Math.max(0,filteredCommands.length-1));renderCommandResults()}else if(e.key==='ArrowUp'){e.preventDefault();commandSelection=Math.max(0,commandSelection-1);renderCommandResults()}else if(e.key==='Enter'){e.preventDefault();runCommand(commandSelection)}else if(e.key==='Escape')closeCommandPalette()};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();q('commandPalette').classList.contains('show')?closeCommandPalette():openCommandPalette()}else if(e.key==='Escape'&&q('commandPalette').classList.contains('show'))closeCommandPalette()});
q('addInbox').onclick=()=>{let text=q('inboxText').value.trim(),details=q('inboxDetails').value.trim();if(!text)return alert('Enter something for the Inbox.');D.inbox.unshift({id:'i'+Date.now().toString(36),type:q('inboxType').value,text,details,date:new Date().toISOString()});q('inboxText').value='';q('inboxDetails').value='';logActivity('Created',text,'Inbox');save()};
