window.convertInbox=(i,target)=>{let item=D.inbox[i];if(!item)return;let out;try{out=window.AIInbox.createFromInbox(item,target,new Date().toISOString())}catch(e){return alert(e.message)}if(out.collection){D[out.collection].unshift(out.value);D.inbox.splice(i,1);logActivity('Converted',activityLabel(item),'Inbox → '+target);save();return}D.inbox.splice(i,1);logActivity('Converted',activityLabel(item),'Inbox → Workspace');save();goV3('workspace');q('workspaceTopic').value=out.value.topic;q('workspaceGoal').value=out.value.goal;q('workspaceTopic').focus()};
