async function refreshProfile(){if(!api?.profileState)return;try{let p=await api.profileState();q('profileHeaderName').textContent=p.enabled?p.name:'';q('lockNowHeader').style.display=p.enabled?'inline-block':'none';q('profileStateText').textContent=p.enabled?'Profile lock enabled for '+p.name+'. API keys are OS-encrypted.':'Profile lock is off. Your API keys are still OS-encrypted.';q('profileNameInput').value=p.name||'';q('lockName').textContent=p.name||'Local profile';q('lockAvatar').textContent=String(p.name||'AI').split(/\s+/).map(x=>x[0]||'').join('').slice(0,2).toUpperCase()||'AI';q('lockScreen').classList.toggle('show',!!p.locked);if(p.locked)setTimeout(()=>q('unlockPin').focus(),50);return p}catch(e){q('profileStateText').textContent='Profile status unavailable: '+e.message}}
q('unlockProfile').onclick=async()=>{q('lockError').textContent='';try{await api.profileUnlock({pin:q('unlockPin').value});q('unlockPin').value='';await refreshProfile()}catch(e){q('lockError').textContent=e.message}};
q('unlockPin').onkeydown=e=>{if(e.key==='Enter')q('unlockProfile').click()};
q('saveProfile').onclick=async()=>{try{let p=await api.profileConfigure({name:q('profileNameInput').value,pin:q('profilePinInput').value});q('profilePinInput').value='';q('profileStateText').textContent='Profile lock enabled for '+p.name+'.';await refreshProfile()}catch(e){q('profileStateText').textContent=e.message}};
q('lockNowHeader').onclick=async()=>{await api.profileLock();await refreshProfile()};
q('lockProfileSettings').onclick=async()=>{let p=await api.profileState();if(!p.enabled)return alert('Create a profile PIN first.');await api.profileLock();await refreshProfile()};
q('disableProfile').onclick=async()=>{if(!confirm('Disable the local profile lock? Your API keys will remain OS-encrypted.'))return;try{await api.profileDisable();await refreshProfile()}catch(e){q('profileStateText').textContent=e.message}};
q('runWorkspace').onclick=async()=>{let topic=q('workspaceTopic').value.trim(),goal=q('workspaceGoal').value.trim();if(!topic&&!goal)return alert('Enter a topic or goal.');q('workspaceBusy').textContent='Researching…';q('runWorkspace').disabled=true;try{let r=await api.workspaceAsk({topic,goal,category:q('workspaceCategory').value,depth:q('workspaceDepth').value,useWeb:q('workspaceWeb').checked});trackUsage(r.usage);lastWorkspaceResult={id:Date.now(),topic:topic||goal.slice(0,70),goal,category:q('workspaceCategory').value,depth:q('workspaceDepth').value,report:r.text,sources:r.sources||[],date:new Date().toISOString()};D.workspaceReports.unshift(lastWorkspaceResult);if(D.workspaceReports.length>50)D.workspaceReports.length=50;q('workspaceAnswer').innerHTML=formatAI(r.text)+sourceLinks(r.sources);q('workspaceResult').style.display='block';q('saveWorkspaceNote').style.display='inline-block';save()}catch(e){q('workspaceAnswer').textContent=e.message;q('workspaceResult').style.display='block'}finally{q('workspaceBusy').textContent='';q('runWorkspace').disabled=false}};
