q('addTech').onclick=()=>{let name=q('techName').value.trim();if(!name)return alert('Enter a build or project name.');D.techBuilds.unshift({name,missionId:q('techMission').value||'',type:q('techType').value,budget:+q('techBudget').value||0,notes:q('techNotes').value.trim(),date:new Date().toISOString()});logActivity('Created',name,'Tech');q('techName').value='';q('techBudget').value='';q('techNotes').value='';save()};
