function doQuickCapture(){let text=q('captureText').value.trim(),type=q('captureType').value;if(!text)return;let date=new Date().toISOString();if(type==='Inbox')D.inbox.unshift({id:'i'+Date.now().toString(36),type:'Idea',text,details:'Captured from Home',date});else if(type==='Note')D.notes.unshift({title:text.slice(0,70),tags:['quick-capture'],body:text,pinned:false,date});else if(type==='Mission')D.missions.unshift({id:'m'+Date.now().toString(36),name:text,outcome:'Captured from Home',category:'Personal',target:'',status:'Idea',progress:0,tasks:[],date,updated:date});else if(type==='Project')D.projects.unshift({name:text,category:'Personal',status:'Idea',progress:0,notes:'Captured from Home',date});else if(type==='Goal')D.goals.unshift({name:text,target:'',progress:0,notes:'Captured from Home',date});else if(type==='Trip')D.trips.unshift({destination:text,start:'',end:'',budget:0,notes:'Captured from Home',date});else if(type==='Tech')D.techBuilds.unshift({name:text,type:'Other',budget:0,notes:'Captured from Home',date});else{q('workspaceTopic').value=text;document.querySelector('[data-view="workspace"]')?.click();q('captureText').value='';return}q('captureText').value='';save()}
q('quickCapture').onclick=doQuickCapture;q('captureText').onkeydown=e=>{if(e.key==='Enter')doQuickCapture()};
async function checkDueReminders(){if(!api?.notify)return;let due=window.AICalendar.dueReminders(D.reminders,Date.now(),6*60*60*1000);for(const item of due){try{let ok=await api.notify({title:'Reminder: '+item.title,body:item.notes||((item.time||'')+(item.kind?' • '+item.kind:''))});if(ok){item.notifiedAt=new Date().toISOString();logActivity('Notified',item.title,'Reminder')}}catch{} }if(due.some(x=>x.notifiedAt))save()}
setTimeout(checkDueReminders,3000);setInterval(checkDueReminders,60000);
refreshProfile();
q('buildPlan').onclick=async()=>{if(!api)return alert('Smart Planner runs in the desktop app.');let budget=Math.max(0,+D.budget||0);if(!budget)return alert('Set your monthly budget first.');q('planBusy').textContent='Building and checking scenarios…';q('buildPlan').disabled=true;try{let r=await api.planAsk({budget,risk:q('planRisk').value,goal:q('planGoal').value});trackUsage(r.usage);let txt=r.text||'';let euros=[...txt.matchAll(/€\s*([0-9]+(?:[.,][0-9]+)?)/g)].map(x=>+x[1].replace(',','.'));q('planResult').innerHTML=formatAI(txt)+(euros.length?'<p class="muted">Check the displayed scenario totals before using them in your planner.</p>':'')}catch(e){q('planResult').textContent=e.message}finally{q('planBusy').textContent='';q('buildPlan').disabled=false}};
q('askSchool').onclick=async()=>{let question=q('schoolQuestion').value.trim();if(!question&&!schoolAttachment)return alert('Enter a topic/question or attach a file first.');if(!question&&schoolAttachment)question=schoolMode==='check'?'Check the attached work and explain any mistakes.':schoolMode==='research'?'Research and help me with the attached assignment.':schoolMode==='teach'?'Teach me the important ideas and methods from the attached file, then give me one similar question to try.':'Explain and help me with the attached file.';if(schoolMode==='practice')question+='\nSubject: '+schoolSubject+'. Practice settings: '+q('practiceDifficulty').value+', '+q('practiceCount').value+' questions total. Adaptive difficulty: '+(q('practiceAdaptive').checked?'on':'off')+'. This is question 1. Give exactly ONE question, do not include the answer or solution, and wait for my answer.';if(schoolMode==='practice'&&pendingWeakContext){question+='\nFocus especially on these previously weak areas:\n'+pendingWeakContext;pendingWeakContext=''}if(schoolMode==='research'){let len=q('schoolResearchLength').value,custom=q('schoolResearchCustomLength').value.trim();question+='\nResearch depth: '+q('schoolResearchDepth').value+'. Desired length: '+(len==='Custom'?(custom||'custom length not specified'):len)+'. Desired output: '+q('schoolResearchOutput').value+'. Match the requested detail and length without padding or repetition. Keep this as research help and structure, not a ready-to-submit assignment unless I explicitly ask for one.'}if(!api)return alert('School AI runs in the desktop app.');q('schoolBusy').textContent=schoolAttachment?'Reading your file and thinking…':'Thinking…';q('askSchool').disabled=true;try{let r=await api.schoolAsk({mode:schoolMode,subject:schoolSubject,question,attachment:schoolAttachment});trackUsage(r.usage);q('schoolAnswer').classList.toggle('reviewout',schoolMode==='check');q('schoolAnswer').classList.toggle('researchout',schoolMode==='research');q('schoolAnswer').innerHTML=formatAI(r.text)+(schoolMode==='research'?sourceLinks(r.sources):'');q('schoolResult').style.display='block';q('practiceAnswerArea').style.display=schoolMode==='practice'?'block':'none';if(schoolMode==='practice'){practiceSession={subject:schoolSubject,topic:q('schoolQuestion').value.trim(),difficulty:q('practiceDifficulty').value,total:+q('practiceCount').value,index:1,correct:0,attempts:0,streak:0,adaptive:q('practiceAdaptive').checked,questions:[q('schoolAnswer').innerText.trim()]};q('practiceAnswer').value='';q('nextPractice').style.display='none';q('checkPractice').style.display='inline-block';q('practiceState').textContent='Question 1/'+practiceSession.total+' • Score 0'}D.school.unshift({mode:schoolMode,subject:schoolSubject,question,answer:r.text,date:new Date().toISOString(),attachment:schoolAttachment?{name:schoolAttachment.name,type:schoolAttachment.type,size:schoolAttachment.size}:null});if(D.school.length>75)D.school.length=75;save()}catch(e){q('schoolAnswer').textContent='Could not run tutor: '+e.message;q('schoolResult').style.display='block'}finally{q('schoolBusy').textContent='';q('askSchool').disabled=false}};
let practiceSession=null,pendingWeakContext='';
function adaptPracticeDifficulty(correct){if(!practiceSession||!practiceSession.adaptive)return;let levels=['Easy','Normal','Hard'],ix=Math.max(0,levels.indexOf(practiceSession.difficulty));if(correct){practiceSession.streak=(practiceSession.streak||0)+1;if(practiceSession.streak>=2&&ix<2){practiceSession.difficulty=levels[ix+1];practiceSession.streak=0}}else{practiceSession.streak=0;if(ix>0)practiceSession.difficulty=levels[ix-1]}q('practiceDifficulty').value=practiceSession.difficulty}
function saveMistake(question,answer,feedback){let item={id:Date.now(),subject:practiceSession?.subject||schoolSubject,topic:practiceSession?.topic||q('schoolQuestion').value.trim()||'Practice',difficulty:practiceSession?.difficulty||q('practiceDifficulty').value,question,answer,feedback,date:new Date().toISOString(),resolved:false};D.mistakes.unshift(item);if(D.mistakes.length>200)D.mistakes.length=200;return item}
q('checkPractice').onclick=async()=>{let answer=q('practiceAnswer').value.trim();if(!answer)return alert('Type your answer first.');if(!api)return;let question=q('schoolAnswer').innerText.trim();q('practiceState').textContent='Checking…';q('checkPractice').disabled=true;try{let subject=practiceSession?.subject||schoolSubject,r=await api.schoolAsk({mode:'practice',subject,question:'Practice question currently shown:\n'+question+'\n\nStudent answer:\n'+answer+'\n\nCheck the answer. The FIRST line must be exactly VERDICT: CORRECT if the answer is fully correct, including any required unit, or VERDICT: NEEDS_FIXING if anything required is missing or wrong. Then briefly explain why and give a helpful correction or hint. Do not give the next question yet.',attachment:null});trackUsage(r.usage);let feedback=r.text||'',correct=/^\s*VERDICT:\s*CORRECT\b/i.test(feedback);feedback=feedback.replace(/^\s*VERDICT:\s*(?:CORRECT|NEEDS_FIXING)\s*/i,'').trim();let st=statFor(subject);st.attempts++;if(correct)st.correct++;if(practiceSession){practiceSession.attempts++;if(correct)practiceSession.correct++}if(!correct)saveMistake(question,answer,feedback);adaptPracticeDifficulty(correct);q('schoolAnswer').innerHTML+='<div class="planOption"><b>'+(correct?'Correct':'Needs fixing')+'</b>'+formatAI(feedback)+(correct?'':'<p class="muted">Saved to Mistake Book.</p>')+'</div>';q('checkPractice').style.display='none';save();if(practiceSession&&practiceSession.index>=practiceSession.total){q('nextPractice').style.display='none';q('practiceState').textContent='Finished • Score '+practiceSession.correct+'/'+practiceSession.total}else{q('nextPractice').style.display='inline-block';q('practiceState').textContent='Question '+(practiceSession?.index||1)+'/'+(practiceSession?.total||'?')+' checked • Score '+(practiceSession?.correct||0)+(practiceSession?.adaptive?' • Next: '+practiceSession.difficulty:'')}}catch(err){q('practiceState').textContent='Could not check: '+err.message}finally{q('checkPractice').disabled=false}};
q('nextPractice').onclick=async()=>{if(!api)return;let topic=practiceSession?.topic||q('schoolQuestion').value.trim(),difficulty=practiceSession?.difficulty||q('practiceDifficulty').value,seen=(practiceSession?.questions||[]).join('\n---\n'),weak=pendingWeakContext;pendingWeakContext='';q('practiceState').textContent='Creating next question…';q('nextPractice').disabled=true;try{let r=await api.schoolAsk({mode:'practice',subject:practiceSession?.subject||schoolSubject,question:'Continue this practice session on '+topic+'. Difficulty: '+difficulty+'. Give exactly ONE new practice question. Do not include the answer or solution. It must be materially different from all previous questions below.'+(weak?' Focus especially on these previously weak areas:\n'+weak:'')+'\nPrevious questions:\n'+seen,attachment:null});trackUsage(r.usage);let txt=r.text||'';if(practiceSession){practiceSession.index++;practiceSession.questions.push(txt)}q('schoolAnswer').innerHTML=formatAI(txt);q('practiceAnswer').value='';q('checkPractice').style.display='inline-block';q('nextPractice').style.display='none';q('practiceState').textContent='Question '+(practiceSession?.index||'?')+'/'+(practiceSession?.total||'?')+' • Score '+(practiceSession?.correct||0)+(practiceSession?.adaptive?' • '+difficulty:'')}catch(err){q('practiceState').textContent='Could not create question: '+err.message}finally{q('nextPractice').disabled=false}};
window.resolveMistake=i=>{if(!D.mistakes[i])return;D.mistakes[i].resolved=!D.mistakes[i].resolved;save()};
window.deleteMistake=i=>{if(!D.mistakes[i])return;D.mistakes.splice(i,1);save()};
window.practiceMistake=i=>{let m=D.mistakes[i];if(!m)return;setSchoolSubject(m.subject||'Other');document.querySelector('.schoolModes [data-mode="practice"]')?.click();q('schoolQuestion').value=m.topic||'Review this weak area';pendingWeakContext='Previous question: '+m.question+'\nYour previous answer: '+m.answer+'\nFeedback: '+m.feedback;q('practiceDifficulty').value=m.difficulty||'Normal';q('askSchool').click()};
q('practiceWeakAreas').onclick=()=>{let active=D.mistakes.filter(m=>!m.resolved),same=active.filter(m=>m.subject===schoolSubject);if(!active.length)return alert('No unresolved mistakes yet.');let targetSubject=same.length?schoolSubject:(active[0].subject||'Other'),pool=active.filter(m=>(m.subject||'Other')===targetSubject);setSchoolSubject(targetSubject);document.querySelector('.schoolModes [data-mode="practice"]')?.click();let topics=[...new Set(pool.slice(0,8).map(m=>m.topic).filter(Boolean))];q('schoolQuestion').value='Weak areas: '+(topics.join(', ')||targetSubject);pendingWeakContext=pool.slice(0,5).map(m=>'Question: '+m.question+'\nFeedback: '+m.feedback).join('\n---\n');q('askSchool').click()};
q('clearResolvedMistakes').onclick=()=>{let n=D.mistakes.filter(m=>m.resolved).length;if(!n)return alert('No learned mistakes to clear.');if(confirm('Remove '+n+' learned mistake'+(n===1?'':'s')+'?')){D.mistakes=D.mistakes.filter(m=>!m.resolved);save()}};
