if(api){api.getAppInfo().then(x=>{q('appVersion').textContent=x.version;q('autoCheck').checked=x.settings.autoCheck!==false;q('keyState').textContent=x.settings.hasOpenAIKey?'API key saved locally.':'No API key saved yet.';q('marketKeyState').textContent=x.settings.hasMarketDataKey?'Twelve Data key saved locally.':'No market-data key saved yet.'});api.onUpdateStatus(upd);q('checkUpdate').onclick=()=>api.checkUpdates();q('installUpdate').onclick=()=>api.installUpdate();q('saveSettings').onclick=async()=>{let s=await api.saveSettings({openaiKey:q('openaiKey').value,autoCheck:q('autoCheck').checked});q('openaiKey').value='';q('keyState').textContent=s.hasOpenAIKey?'API key saved locally.':'No API key saved.'};q('testApi').onclick=async()=>{q('keyState').textContent='Testing API connection…';try{let r=await api.testApi();q('keyState').textContent=r.ok?'API connection successful.':'Connection test failed.'}catch(e){q('keyState').textContent='Connection failed: '+e.message}};q('clearKey').onclick=async()=>{await api.saveSettings({clearKey:true,autoCheck:q('autoCheck').checked});q('keyState').textContent='API key cleared.'};q('saveMarketData').onclick=async()=>{let s=await api.saveSettings({marketDataKey:q('marketDataKey').value,autoCheck:q('autoCheck').checked});q('marketDataKey').value='';q('marketKeyState').textContent=s.hasMarketDataKey?'Twelve Data key saved locally.':'No market-data key saved.'};q('testMarketData').onclick=async()=>{q('marketKeyState').textContent='Testing Twelve Data…';try{let r=await api.testMarketData();q('marketKeyState').textContent='Connected • '+r.symbol+(r.price?' • '+r.price:'')+(r.usage&&r.usage.left?' • '+r.usage.left+' credits left this minute':'')}catch(e){q('marketKeyState').textContent='Connection failed: '+e.message}};q('clearMarketData').onclick=async()=>{await api.saveSettings({clearMarketDataKey:true,autoCheck:q('autoCheck').checked});q('marketKeyState').textContent='Market-data key cleared.'};q('runDiag').onclick=async()=>{q('diagState').textContent='Running diagnostics…';try{let [d,info]=await Promise.all([api.diagnostics(),api.getAppInfo()]);let lines=['Diagnostics completed','App version: '+(info.version||'unknown'),'OpenAI key: '+(info.settings?.hasKey?'saved':'not saved'),'Market-data key: '+(info.settings?.hasMarketDataKey?'saved':'not saved'),'','Recent log:'];lines.push(d.text&&d.text!=='No diagnostic events logged yet.'?d.text:'No errors or diagnostic events logged.');q('diagState').textContent=lines.join('\n')}catch(e){q('diagState').textContent='Diagnostics failed: '+e.message}};q('copyDiag').onclick=async()=>{let d=await api.diagnostics();try{await navigator.clipboard.writeText(d.text);q('diagState').textContent='Diagnostic report copied.'}catch{q('diagState').textContent='Could not access clipboard. Log location: '+d.path}};q('clearLogs').onclick=async()=>{await api.clearLogs();q('diagState').textContent='Logs cleared.'}}else q('updateStatus').textContent='Desktop-only controls unavailable in browser.';
q('exportBtn').onclick=()=>{let blob=new Blob([JSON.stringify(D,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='AI-Research-V3.0.0-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
q('globalSearch').oninput=()=>{let s=q('globalSearch').value.trim().toLowerCase();if(!s){q('searchResults').textContent='Start typing to search your saved data.';return}let hits=[];D.research.forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(s))hits.push('Research — '+x.name)});D.watch.forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(s))hits.push('Watchlist — '+x.ticker)});D.school.forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(s))hits.push('School — '+String(x.question||x.subject||'Session').slice(0,80))});D.mistakes.forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(s))hits.push('Mistake — '+(x.subject||'School')+' — '+String(x.topic||x.question||'').slice(0,70))});[['Inbox',D.inbox],['Mission',D.missions],['Project',D.projects],['Note',D.notes],['Trip',D.trips],['Goal',D.goals],['Tech',D.techBuilds],['Workspace',D.workspaceReports]].forEach(([label,list])=>list.forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(s))hits.push(label+' — '+String(x.name||x.title||x.destination||x.topic||'Item').slice(0,70))}));q('searchResults').innerHTML=hits.length?hits.slice(0,12).map(x=>'<div style="padding:6px 0">'+esc(x)+'</div>').join(''):'No matches.'};
function normalizeData(x={}){return window.AIData.normalizeData(x)}
q('importBtn').onclick=()=>q('importFile').click();q('importFile').onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{D=normalizeData(JSON.parse(r.result));migrateV25();save();renderUsage();alert('Backup imported successfully.')}catch{alert('Invalid backup.')}};r.readAsText(f)};
